solution:
book = {}
while True:
    line = input()
    if line == "quit":
        break
    parts = line.split()
    if parts[0] == "add":
        book[parts[1]] = parts[2]
    elif parts[0] == "find":
        print(book.get(parts[1], "not found"))

alt:
book = {}
line = input()
while line != "quit":
    cmd, name, *rest = line.split() + [""]
    if cmd == "add":
        book[name] = rest[0]
    elif cmd == "find":
        print(book[name] if name in book else "not found")
    line = input()
